((stacked)=>{
const W=document.documentElement.clientWidth, bad=[];
const name=e=>e.tagName.toLowerCase()+'.'+[...e.classList].join('.');
for(const e of document.querySelectorAll('.screen__body *, .sheet *')){const r=e.getBoundingClientRect();
 if(r.width>0&&r.right>W+1&&!e.closest('[data-scroll-x], .cmd, pre, .xterm, .cm-editor, .chips'))bad.push('past the edge: '+name(e)+' '+Math.round(r.right));}
const room=(el)=>(el.closest('dl, header, .work-actions, .work-review, .work-stack, .sheet')??el.parentElement).clientWidth*0.85;
const split=(el)=>{const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);for(let n;(n=w.nextNode());){const re=/[^\s\-–—\/]+/g;let m;
 while((m=re.exec(n.data))){const g=document.createRange();g.setStart(n,m.index);g.setEnd(n,m.index+m[0].length);
  const rs=[...g.getClientRects()].filter(x=>x.width>0);const lines=new Set(rs.map(x=>Math.round(x.bottom)));
  const width=rs.reduce((a,x)=>a+x.width,0);if(lines.size>1&&width<=room(el))bad.push('split word: '+JSON.stringify(m[0])+' in '+name(el));}}};
document.querySelectorAll('.work-facts dt, .work-facts dd, .work-receipt-head h1, .work-screen .btn, .work-sheet .btn, .sheet .btn').forEach(split);
for(const b of document.querySelectorAll('.work-screen .btn, .work-sheet .btn, .sheet .btn')){const l=b.querySelector('.btn__label')??b;
 const br=b.getBoundingClientRect(),lr=l.getBoundingClientRect();if(br.width&&(lr.left<br.left-1||lr.right>br.right+1||b.scrollWidth>b.clientWidth+1))bad.push('label spills: '+JSON.stringify(b.textContent));}
if(stacked!==null)for(const row of document.querySelectorAll('.work-facts > div')){const t=row.querySelector('dt').getBoundingClientRect(),d=row.querySelector('dd').getBoundingClientRect();
 if((d.top>=t.bottom-1)!==stacked)bad.push((stacked?'value beside ':'value under ')+JSON.stringify(row.querySelector('dt').textContent));}
if(bad.length)throw Error([...new Set(bad)].slice(0,8).join('; '));
return 'ok: '+document.querySelectorAll('.work-facts > div').length+' facts, '+document.querySelectorAll('.work-screen .btn, .sheet .btn').length+' buttons';
})(true)

